import * as React from "react";
import { cn } from "@/lib/utils";

export interface BottomNavProps extends React.HTMLAttributes<HTMLElement> {
  /**
   * Maximum width constraint for the nav bar
   * @default "max-w-lg"
   */
  maxWidth?: string;
}

/**
 * A pill-shaped bottom navigation bar component.
 *
 * Features:
 * - Fixed to bottom with safe area padding
 * - Constrained width matching content containers
 * - Fully rounded (pill-shaped)
 * - Spacing on left, right, and bottom edges
 *
 * @example
 * ```tsx
 * <BottomNav>
 *   <BottomNavItem href="/" active>
 *     <HomeIcon />
 *     <span>Home</span>
 *   </BottomNavItem>
 *   <BottomNavItem href="/settings">
 *     <SettingsIcon />
 *     <span>Settings</span>
 *   </BottomNavItem>
 * </BottomNav>
 * ```
 */
const BottomNav = React.forwardRef<HTMLElement, BottomNavProps>(
  ({ className, maxWidth = "max-w-lg", children, ...props }, ref) => (
    <nav
      ref={ref}
      className={cn(
        // Positioning with spacing from edges. The bottom gap is the LARGER of
        // the float gap or (the safe-area inset minus a little) -- the raw inset
        // floats the pill too high above a transparent home indicator, so trim
        // it; the max() keeps a real gap on web/Android where the inset is ~0.
        "fixed bottom-0 left-2 right-2 z-50",
        "bottom-nav-safe",
        className
      )}
      {...props}
    >
      <div
        className={cn(
          // Size and centering - content-based width with maximum
          "w-fit",
          maxWidth,
          "mx-auto",
          // Pill shape
          "rounded-full",
          // Frosted glass effect
          "wj-frost-chrome",
          "border border-[var(--color-border-light)] dark:border-[var(--color-border-dark)]",
          // Shadow for elevation
          "shadow-lg",
          // Layout
          "flex items-center gap-1 h-16 px-2"
        )}
      >
        {children}
      </div>
    </nav>
  )
);
BottomNav.displayName = "BottomNav";

export interface BottomNavItemProps extends React.HTMLAttributes<HTMLElement> {
  /**
   * Whether this nav item is currently active
   */
  active?: boolean;
  /**
   * The element type to render (for use with router Link components)
   * @default "a"
   */
  as?: React.ElementType;
  /**
   * Href for the navigation item (passed to the underlying element)
   */
  href?: string;
  /**
   * For react-router-dom Link components, use "to" instead of "href"
   */
  to?: string;
}

/**
 * Individual navigation item within BottomNav.
 *
 * Supports custom elements via the `as` prop for router integration:
 *
 * @example
 * ```tsx
 * import { Link } from 'react-router-dom'
 *
 * <BottomNavItem as={Link} to="/home" active>
 *   <HomeIcon />
 *   <span>Home</span>
 * </BottomNavItem>
 * ```
 */
const BottomNavItem = React.forwardRef<HTMLElement, BottomNavItemProps>(
  ({ className, active, as: Component = "a", children, ...props }, ref) => (
    <Component
      ref={ref}
      className={cn(
        "wj-focus-ring flex flex-col items-center justify-center px-4 py-2 rounded-xl transition-colors touch-target",
        active
          ? "text-[var(--color-warm-800)] dark:text-white"
          : "text-[var(--color-text-muted-light)] dark:text-[var(--color-text-muted-dark)]",
        className
      )}
      {...props}
    >
      {children}
    </Component>
  )
);
BottomNavItem.displayName = "BottomNavItem";

export interface BottomNavActionProps extends React.HTMLAttributes<HTMLElement> {
  /**
   * The element type to render (for use with router Link components)
   * @default "a"
   */
  as?: React.ElementType;
  /**
   * Href for the action (passed to the underlying element)
   */
  href?: string;
  /**
   * For react-router-dom Link components, use "to" instead of "href"
   */
  to?: string;
}

/**
 * Action button within BottomNav (e.g., add button).
 *
 * Uses the solid accent color for action buttons.
 *
 * @example
 * ```tsx
 * import { Link } from 'react-router-dom'
 *
 * <BottomNavAction as={Link} to="/add" aria-label="Add">
 *   <PlusIcon />
 * </BottomNavAction>
 * ```
 */
const BottomNavAction = React.forwardRef<HTMLElement, BottomNavActionProps>(
  ({ className, as: Component = "a", children, ...props }, ref) => (
    <Component
      ref={ref}
      className={cn(
        "wj-focus-ring w-12 h-12 rounded-full flex items-center justify-center",
        "bg-[var(--color-accent-500)] shadow-bevel-accent",
        "hover:bg-[var(--color-accent-400)]",
        "active:bg-[var(--color-accent-600)]",
        "text-[var(--color-accent-foreground-icon)] transition-all",
        "hover:scale-105 active:scale-95",
        className
      )}
      {...props}
    >
      {children}
    </Component>
  )
);
BottomNavAction.displayName = "BottomNavAction";

export { BottomNav, BottomNavItem, BottomNavAction };
